#!/usr/bin/env bash
set -euo pipefail
DEST="${ECC_DEST:-$HOME/vhdl_repo/IP_Cores/ECC_Scrubber}"
VIV="$DEST/vivado"
RTL="$DEST/rtl"
mkdir -p "$VIV" "$RTL"
echo ">> destino vivado: $VIV"
echo ">> destino rtl:    $RTL"
echo "" | base64 -d > "$RTL/soc_top_ecc_wrap.v"
echo "" | base64 -d > "$VIV/gen_ecc_bd_tcl.sh"; chmod +x "$VIV/gen_ecc_bd_tcl.sh"
echo "" | base64 -d > "$DEST/ecc_selftest.c"
echo ">> wrapper Verilog: $(wc -l < "$RTL/soc_top_ecc_wrap.v") lineas"
echo ">> script cirugia:  $(wc -l < "$VIV/gen_ecc_bd_tcl.sh") lineas"
echo ">> selftest (AXIL_BASE=0xA4000000): $(grep -c 0xA4000000 "$DEST/ecc_selftest.c") ref"
echo ">> listo. Siguiente: correr gen_ecc_bd_tcl.sh y luego el flujo Vivado."
